export const SOCIAL_PLATFORMS = [
  {
    key: 'whatsapp',
    label: 'WhatsApp',
    Icon: WhatsAppIcon,
    color: '#25D366',
    urlField: 'whatsapp',
    handleField: null,
    buildUrl: (value) => {
      const digits = String(value || '').replace(/[^0-9]/g, '');
      return digits ? `https://wa.me/${digits}` : '';
    },
    buildLabel: (value) => (value ? String(value) : ''),
  },
  {
    key: 'instagram',
    label: 'Instagram',
    Icon: InstagramIcon,
    color: '#E1306C',
    urlField: 'instagramUrl',
    handleField: 'instagramHandle',
  },
  {
    key: 'facebook',
    label: 'Facebook',
    Icon: FacebookIcon,
    color: '#1877F2',
    urlField: 'facebookUrl',
    handleField: 'facebookHandle',
  },
  {
    key: 'x',
    label: 'X',
    Icon: XIcon,
    color: '#000000',
    urlField: 'xUrl',
    handleField: 'xHandle',
  },
  {
    key: 'twitch',
    label: 'External Link',
    Icon: ExternalLinkIcon,
    color: '#6B7280',
    urlField: 'twitchUrl',
    handleField: 'twitchHandle',
  },
  {
    key: 'tiktok',
    label: 'TikTok',
    Icon: TikTokIcon,
    color: '#000000',
    urlField: 'tiktokUrl',
    handleField: 'tiktokHandle',
  },
  {
    key: 'pinterest',
    label: 'Pinterest',
    Icon: PinterestIcon,
    color: '#E60023',
    urlField: 'pinterestUrl',
    handleField: 'pinterestHandle',
  },
];

export function buildVendorSocialLinks(social) {
  if (!social) return [];
  return SOCIAL_PLATFORMS.map((platform) => {
    if (platform.key === 'whatsapp') {
      const href = platform.buildUrl(social.whatsapp);
      if (!href) return null;
      return { key: platform.key, label: platform.label, Icon: platform.Icon, color: platform.color, href, sublabel: social.whatsapp };
    }
    const href = String(social[platform.urlField] || '').trim();
    if (!href) return null;
    const sublabel = platform.handleField ? String(social[platform.handleField] || '').trim() : '';
    return { key: platform.key, label: platform.label, Icon: platform.Icon, color: platform.color, href, sublabel };
  }).filter(Boolean);
}
